export const resetInitialState = {
    field: Array(9).fill(""),
    currentPlayer: "X",
    isGameEnded: false,
    isDraw: false,
    massiveX: [],
    massiveO: [],
  };

export const resetReducer = (state = resetInitialState, action) => {
  switch (action.type) {
    case "RESET_GAME":
      return {
        ...resetInitialState,
      };
    default:
      return state;
  }
};
